def lies(pfad):
    with open(pfad, encoding="utf-8") as f:
        for zeile in f:
            yield zeile.rstrip("\n")

def nur_fehler(zeilen):
    for z in zeilen:
        if " ERROR " in z:
            yield z

# Testdatei erzeugen
with open("server.log", "w",
          encoding="utf-8") as f:
    for i in range(100_000):
        s = "ERROR" if i % 1000 == 0 else "INFO"
        f.write(f"{i} {s} Anfrage\n")

fehler = nur_fehler(lies("server.log"))
print(next(fehler))   # 0 ERROR Anfrage
print(sum(1 for _ in fehler))   # 99

